  RefPtr<CSSValue> PropertyParsing::ConsumeViewTimelineAxis(TokenRange &range) noexcept
  {
    // [ block | inline | x | y ]#
    auto ConsumeUnboundedRepetition = [](TokenRange &tokens) -> RefPtr<CSSValue>
    {
      auto ConsumeRepeatedTerm = [](TokenRange &tokens) -> RefPtr<CSSValue>
      {
        // block | inline | x | y
        switch (auto keyword = tokens.Peek().ValueId(); keyword)
        {
          case ValueId::Block:
          case ValueId::Inline:
          case ValueId::X:
          case ValueId::Y:
          {
            tokens.Discard();
            tokens.DiscardWhitespace();

            return CSSPrimitiveValue::Create(keyword);
          }
          default:
          {
            return nullptr;
          }
        }
      };

      return ConsumeListSeparatedBy<',', ListBounds::MinimumOf(1), ListOptimization::SingleValue, CSSValueList>(tokens, ConsumeRepeatedTerm);
    };

    return ConsumeUnboundedRepetition(range);
  }

