  RefPtr<CSSValue> PropertyParsing::ConsumeContainIntrinsicHeight(TokenRange &range, PropertyParserState &state) noexcept
  {
    // [ auto? [ none | <length [0,inf]> ] ]@(type=CSSValuePair)
    auto ConsumeMatchAllOrdered = [](TokenRange &tokens, PropertyParserState &state) -> RefPtr<CSSValue>
    {
      auto ConsumeTerm0 = [](TokenRange &tokens) -> RefPtr<CSSValue>
      {
        // auto
        switch (auto keyword = tokens.Peek().ValueId(); keyword)
        {
          case ValueId::Auto:
          {
            tokens.Discard();
            tokens.DiscardWhitespace();

            return CSSPrimitiveValue::Create(keyword);
          }
          default:
          {
            return nullptr;
          }
        }
      };

      auto ConsumeTerm1 = [](TokenRange &tokens, PropertyParserState &state) -> RefPtr<CSSValue>
      {
        // none
        switch (auto keyword = tokens.Peek().ValueId(); keyword)
        {
          case ValueId::None:
          {
            tokens.Discard();
            tokens.DiscardWhitespace();

            return CSSPrimitiveValue::Create(keyword);
          }
          default:
          {
            break;
          }
        }

        // <length [0,inf]>
        return CSSPrimitiveValueResolver<Length<CSSRange{0, CSSRange::Inf}>>::ConsumeAndResolve(tokens, state, {.UnitlessZeroLength = AllowUnitlessZero(true)});
      };


      CSSValueListBuilder list;
      // auto?
      auto value0 = ConsumeTerm0(tokens);
      if (value0)
      {
        list.push_back(krys::move(value0));
      }

      // [ none | <length [0,inf]> ]
      auto value1 = ConsumeTerm1(tokens, state);
      if (value1)
      {
        list.push_back(krys::move(value1));
      }
      else
      {
        return {};
      }

      if (list.size() == 1)
      {
        return krys::move(list[0]); // single item optimization
      }

      return CSSValuePair::Create(krys::move(list[0]), krys::move(list[1]));
    };

    return ConsumeMatchAllOrdered(range, state);
  }

