  RefPtr<CSSValue> PropertyParsing::ConsumeCornerStartEndShape(TokenRange &range, PropertyParserState &state) noexcept
  {
    // bevel | notch | round | scoop | squircle | straight
    if (auto result = ConsumeIdent(range, IsKeywordValidForCornerStartEndShape))
    {
      return result;
    }

    // superellipse([ <number [0,inf]> | infinity ])
    auto ConsumeSuperellipseFunction = [](TokenRange &tokens, PropertyParserState &state) -> RefPtr<CSSValue>
    {
      auto ConsumeParameters = [](TokenRange &args, PropertyParserState &state) -> Maybe<CSSValueListBuilder>
      {
        auto ConsumeParameter = [](TokenRange &args, PropertyParserState &state) -> RefPtr<CSSValue>
        {
          // infinity
          switch (auto keyword = args.Peek().ValueId(); keyword)
          {
            case ValueId::Infinity:
            {
              args.Discard();
              args.DiscardWhitespace();

              return CSSPrimitiveValue::Create(keyword);
            }
            default:
            {
              break;
            }
          }

          // <number [0,inf]>
          return CSSPrimitiveValueResolver<Number<CSSRange{0, CSSRange::Inf}>>::ConsumeAndResolve(args, state);
        };

        auto parameter = ConsumeParameter(args, state);
        if (!parameter)
        {
          return {};
        }

        return CSSValueListBuilder {krys::move(parameter)};
      };

      if (tokens.Peek().FunctionId() != ValueId::Superellipse)
      {
        return {};
      }

      TokenRange tokensCopy = tokens;
      TokenRange args = ConsumeFunction(tokensCopy);

      auto result = ConsumeParameters(args, state);
      if (!result.has_value())
      {
        return {};
      }

      if (!args.IsAtEnd())
      {
        return {};
      }

      tokens = tokensCopy;
      return CSSFunctionValue::Create(ValueId::Superellipse, krys::move(result.value()));
    };

    return ConsumeSuperellipseFunction(range, state);
  }

